    {"label": "Prevention by breaking a condition", "description": "E.g. global lock ordering removes circular wait; requesting all resources removes hold and wait.", "keywords": ["ordering", "break", "request all", "preemption", "prevent"], "core": true},
    {"label": "Avoidance and detection", "description": "Banker's algorithm avoids deadlock; wait-for graphs detect it.", "keywords": ["banker", "avoidance", "detection", "wait-for graph", "recovery"], "core": false}
